import type { Experimental_SandboxSession as SandboxSession } from '@ai-sdk/provider-utils';
import { describe, expect, it, vi } from 'vitest';
import type { HarnessV1Bootstrap } from '../../v1';
import {
  BOOTSTRAP_SCHEMA_VERSION,
  applyBootstrapRecipe,
  bootstrapMarkerPath,
  hashHarnessBootstrap,
} from './bootstrap-recipe';

const baseRecipe: HarnessV1Bootstrap = {
  harnessId: 'demo',
  bootstrapDir: '/tmp/harness/demo',
  files: [
    { path: '/tmp/harness/demo/a.txt', content: 'one' },
    { path: '/tmp/harness/demo/b.txt', content: 'two' },
  ],
  commands: [{ command: 'echo first' }, { command: 'echo second' }],
};
const stateDirectory = '/work';

describe('hashHarnessBootstrap', () => {
  it('produces a deterministic 16-char hex id for the same recipe', async () => {
    const a = await hashHarnessBootstrap(baseRecipe);
    const b = await hashHarnessBootstrap(baseRecipe);
    expect(a).toBe(b);
    expect(a).toMatch(/^[0-9a-f]{16}$/);
  });

  it('is unaffected by file ordering in the recipe', async () => {
    const reordered: HarnessV1Bootstrap = {
      ...baseRecipe,
      files: [...baseRecipe.files].reverse(),
    };
    expect(await hashHarnessBootstrap(baseRecipe)).toBe(
      await hashHarnessBootstrap(reordered),
    );
  });

  it('changes when a file content changes', async () => {
    const altered: HarnessV1Bootstrap = {
      ...baseRecipe,
      files: [
        { path: '/tmp/harness/demo/a.txt', content: 'one!' },
        baseRecipe.files[1],
      ],
    };
    expect(await hashHarnessBootstrap(altered)).not.toBe(
      await hashHarnessBootstrap(baseRecipe),
    );
  });

  it('changes when a command changes', async () => {
    const altered: HarnessV1Bootstrap = {
      ...baseRecipe,
      commands: [{ command: 'echo different' }],
    };
    expect(await hashHarnessBootstrap(altered)).not.toBe(
      await hashHarnessBootstrap(baseRecipe),
    );
  });

  it('changes when harnessId changes', async () => {
    const altered: HarnessV1Bootstrap = { ...baseRecipe, harnessId: 'other' };
    expect(await hashHarnessBootstrap(altered)).not.toBe(
      await hashHarnessBootstrap(baseRecipe),
    );
  });

  it('changes when bootstrapDir changes', async () => {
    const altered: HarnessV1Bootstrap = {
      ...baseRecipe,
      bootstrapDir: '/tmp/other',
    };
    expect(await hashHarnessBootstrap(altered)).not.toBe(
      await hashHarnessBootstrap(baseRecipe),
    );
  });

  it('includes the harness state directory in the recipe identity', async () => {
    expect(await hashHarnessBootstrap(baseRecipe)).toMatchInlineSnapshot(
      '"2b1b95adf78b2953"',
    );
  });
});

describe('bootstrapMarkerPath', () => {
  it('embeds the identity in the filename under bootstrapDir', () => {
    expect(
      bootstrapMarkerPath({
        recipe: baseRecipe,
        identity: 'abc1234567890def',
        stateDirectory,
      }),
    ).toBe('/tmp/harness/demo/.bootstrap-abc1234567890def.ok');
  });

  it('resolves a relative bootstrapDir against the state directory', () => {
    expect(
      bootstrapMarkerPath({
        recipe: {
          ...baseRecipe,
          bootstrapDir: '.harness-bootstrap/demo',
        },
        identity: 'abc1234567890def',
        stateDirectory,
      }),
    ).toBe('/work/.harness-bootstrap/demo/.bootstrap-abc1234567890def.ok');
  });
});

describe('applyBootstrapRecipe', () => {
  const identity = 'idtest1234567890';

  function makeMockSession(opts?: {
    markerExists?: boolean;
    directoryExitCode?: number;
    commandExitCode?: number;
    runFailureMessage?: string;
  }): {
    session: SandboxSession;
    readTextFile: ReturnType<typeof vi.fn>;
    writeTextFile: ReturnType<typeof vi.fn>;
    run: ReturnType<typeof vi.fn>;
  } {
    const markerPath = bootstrapMarkerPath({
      recipe: baseRecipe,
      identity,
      stateDirectory,
    });
    const readTextFile = vi.fn(async (args: { path: string }) => {
      if (args.path === markerPath && opts?.markerExists) return '';
      return null;
    });
    const writeTextFile = vi.fn(async (_args: { path: string }) => {});
    const run = vi.fn(
      async (args: {
        command: string;
        workingDirectory?: string;
        env?: Record<string, string>;
      }) => {
        const isDirectoryCreation =
          args.command === 'mkdir -p "$BOOTSTRAP_DIR"';
        return {
          exitCode: isDirectoryCreation
            ? (opts?.directoryExitCode ?? 0)
            : (opts?.commandExitCode ?? 0),
          stdout: 'ok',
          stderr: opts?.runFailureMessage ?? '',
        };
      },
    );
    const session = {
      description: 'mock',
      readTextFile,
      writeTextFile,
      run,
    } as unknown as SandboxSession;
    return { session, readTextFile, writeTextFile, run };
  }

  it('skips when the marker file is present', async () => {
    const { session, readTextFile, writeTextFile, run } = makeMockSession({
      markerExists: true,
    });
    await applyBootstrapRecipe({
      session,
      recipe: baseRecipe,
      identity,
      stateDirectory,
    });
    expect(readTextFile).toHaveBeenCalledTimes(1);
    expect(writeTextFile).not.toHaveBeenCalled();
    expect(run).not.toHaveBeenCalled();
  });

  it('creates the bootstrap directory, writes files, runs commands there, and writes the marker', async () => {
    const { session, writeTextFile, run } = makeMockSession();
    await applyBootstrapRecipe({
      session,
      recipe: baseRecipe,
      identity,
      stateDirectory,
    });
    expect(writeTextFile).toHaveBeenCalledTimes(
      baseRecipe.files.length + 1, // recipe files + marker
    );
    expect(run).toHaveBeenCalledTimes(baseRecipe.commands.length + 1);
    expect(run).toHaveBeenNthCalledWith(1, {
      command: 'mkdir -p "$BOOTSTRAP_DIR"',
      env: { BOOTSTRAP_DIR: '/tmp/harness/demo' },
      abortSignal: undefined,
    });
    expect(run.mock.calls.map(([args]) => args.workingDirectory)).toEqual([
      undefined,
      '/tmp/harness/demo',
      '/tmp/harness/demo',
    ]);
    expect(run.mock.invocationCallOrder[0]!).toBeLessThan(
      writeTextFile.mock.invocationCallOrder[0]!,
    );
    const lastWrite = writeTextFile.mock.calls.at(-1)![0];
    expect(lastWrite.path).toBe(
      bootstrapMarkerPath({
        recipe: baseRecipe,
        identity,
        stateDirectory,
      }),
    );
  });

  it('resolves relative paths and runs commands from the bootstrap directory', async () => {
    const relativeRecipe: HarnessV1Bootstrap = {
      harnessId: 'demo',
      bootstrapDir: '.harness-bootstrap/demo',
      files: [
        {
          path: '.harness-bootstrap/demo/file.txt',
          content: 'content',
        },
      ],
      commands: [{ command: 'echo first' }, { command: 'echo second' }],
    };
    const { session, readTextFile, writeTextFile, run } = makeMockSession();

    await applyBootstrapRecipe({
      session,
      recipe: relativeRecipe,
      identity,
      stateDirectory,
    });

    expect(readTextFile).toHaveBeenCalledWith({
      path: '/work/.harness-bootstrap/demo/.bootstrap-idtest1234567890.ok',
      abortSignal: undefined,
    });
    expect(writeTextFile.mock.calls.map(([args]) => args.path)).toEqual([
      '/work/.harness-bootstrap/demo/file.txt',
      '/work/.harness-bootstrap/demo/.bootstrap-idtest1234567890.ok',
    ]);
    expect(run.mock.calls.map(([args]) => args.workingDirectory)).toEqual([
      undefined,
      '/work/.harness-bootstrap/demo',
      '/work/.harness-bootstrap/demo',
    ]);
  });

  it('throws when a command exits non-zero and skips the marker write', async () => {
    const { session, writeTextFile, run } = makeMockSession({
      commandExitCode: 7,
      runFailureMessage: 'boom',
    });
    await expect(
      applyBootstrapRecipe({
        session,
        recipe: baseRecipe,
        identity,
        stateDirectory,
      }),
    ).rejects.toThrow(/Bootstrap command failed.*exit 7.*boom/s);
    expect(run).toHaveBeenCalledTimes(2);
    const markerWrites = writeTextFile.mock.calls.filter(
      ([args]) =>
        args.path ===
        bootstrapMarkerPath({
          recipe: baseRecipe,
          identity,
          stateDirectory,
        }),
    );
    expect(markerWrites).toHaveLength(0);
  });

  it('stops before writing files when bootstrap directory creation fails', async () => {
    const { session, writeTextFile, run } = makeMockSession({
      directoryExitCode: 9,
      runFailureMessage: 'mkdir failed',
    });

    await expect(
      applyBootstrapRecipe({
        session,
        recipe: baseRecipe,
        identity,
        stateDirectory,
      }),
    ).rejects.toThrow(
      /Failed to create bootstrap directory.*exit 9.*mkdir failed/s,
    );
    expect(run).toHaveBeenCalledTimes(1);
    expect(writeTextFile).not.toHaveBeenCalled();
  });
});

describe('BOOTSTRAP_SCHEMA_VERSION', () => {
  it('is a positive integer', () => {
    expect(Number.isInteger(BOOTSTRAP_SCHEMA_VERSION)).toBe(true);
    expect(BOOTSTRAP_SCHEMA_VERSION).toBeGreaterThan(0);
  });
});

import { describe, expect, it, vi } from 'vitest';
import type { FetchFunction } from '@ai-sdk/provider-utils';
import { auth, type OAuthClientProvider } from './oauth';
import type { OAuthTokens } from './oauth-types';
import { InvalidGrantError } from '../error/oauth-error';

const serverUrl = 'https://api.example.com/mcp';
const authorizationServerInformation = {
  authorizationServerUrl: 'https://auth.example.com',
  tokenEndpoint: 'https://auth.example.com/token',
};
const oldTokens: OAuthTokens = {
  access_token: 'old-access',
  refresh_token: 'old-refresh',
  token_type: 'Bearer',
};
const newTokens: OAuthTokens = {
  access_token: 'new-access',
  refresh_token: 'new-refresh',
  token_type: 'Bearer',
};

function createProvider(store: { tokens?: OAuthTokens }) {
  const provider = {
    redirectUrl: 'http://localhost:3000/callback',
    clientMetadata: { redirect_uris: ['http://localhost:3000/callback'] },
    clientInformation: () => ({ client_id: 'shared-client' }),
    authorizationServerInformation: () => authorizationServerInformation,
    saveAuthorizationServerInformation: vi.fn(),
    tokens: () => store.tokens,
    saveTokens: vi.fn((tokens: OAuthTokens) => {
      store.tokens = tokens;
    }),
    invalidateCredentials: vi.fn(
      (
        scope: Parameters<
          NonNullable<OAuthClientProvider['invalidateCredentials']>
        >[0],
        context?: { tokens: OAuthTokens },
      ) => {
        if (scope === 'tokens' || scope === 'all') {
          // No await between comparison and deletion: atomic for this memory store.
          if (
            !context ||
            (store.tokens?.access_token === context.tokens.access_token &&
              store.tokens?.refresh_token === context.tokens.refresh_token)
          ) {
            store.tokens = undefined;
          }
        }
      },
    ),
    redirectToAuthorization: vi.fn(),
    saveCodeVerifier: vi.fn(),
    codeVerifier: () => 'verifier',
  } satisfies OAuthClientProvider;
  return provider;
}

function createFetch(
  handleToken: (params: URLSearchParams) => Response | Promise<Response>,
): FetchFunction {
  return async (input, init) => {
    const url = String(input);
    if (url.includes('/.well-known/oauth-protected-resource')) {
      return Response.json({
        resource: serverUrl,
        authorization_servers: ['https://auth.example.com'],
      });
    }
    if (url.includes('/.well-known/oauth-authorization-server')) {
      return Response.json({
        issuer: 'https://auth.example.com',
        authorization_endpoint: 'https://auth.example.com/authorize',
        token_endpoint: authorizationServerInformation.tokenEndpoint,
        response_types_supported: ['code'],
        grant_types_supported: ['authorization_code', 'refresh_token'],
        code_challenge_methods_supported: ['S256'],
      });
    }
    if (url === authorizationServerInformation.tokenEndpoint) {
      return handleToken(init?.body as URLSearchParams);
    }
    return new Response(null, { status: 404 });
  };
}

function invalidGrant() {
  return Response.json({ error: 'invalid_grant' }, { status: 400 });
}

function deferred() {
  let resolve!: () => void;
  const promise = new Promise<void>(r => {
    resolve = r;
  });
  return { promise, resolve };
}

describe('OAuth credential invalidation', () => {
  it('preserves a concurrent refresh winner in shared storage and retries its tokens', async () => {
    const store = { tokens: { ...oldTokens } as OAuthTokens | undefined };
    const first = createProvider(store);
    const second = createProvider(store);
    const bothRefreshing = deferred();
    const winnerSaved = deferred();
    let oldRefreshes = 0;
    const refreshTokens: string[] = [];

    for (const provider of [first, second]) {
      provider.saveTokens.mockImplementation(tokens => {
        store.tokens = tokens;
        winnerSaved.resolve();
      });
    }

    const fetchFn = createFetch(async params => {
      const refreshToken = params.get('refresh_token')!;
      refreshTokens.push(refreshToken);
      if (refreshToken === oldTokens.refresh_token) {
        const attempt = ++oldRefreshes;
        if (attempt === 2) bothRefreshing.resolve();
        await bothRefreshing.promise;
        if (attempt === 2) {
          await winnerSaved.promise;
          return invalidGrant();
        }
      }
      return Response.json(newTokens);
    });

    const results = await Promise.all([
      auth(first, { serverUrl, fetchFn }),
      auth(second, { serverUrl, fetchFn }),
    ]);

    expect(results).toEqual(['AUTHORIZED', 'AUTHORIZED']);
    expect(store.tokens).toMatchObject(newTokens);
    expect(refreshTokens).toEqual([
      'old-refresh',
      'old-refresh',
      'new-refresh',
    ]);
    expect([
      ...first.invalidateCredentials.mock.calls,
      ...second.invalidateCredentials.mock.calls,
    ]).toEqual([['tokens', { tokens: oldTokens }]]);
    expect(first.redirectToAuthorization).not.toHaveBeenCalled();
    expect(second.redirectToAuthorization).not.toHaveBeenCalled();
  });

  it('deletes a rejected generation that is still stored and starts authorization', async () => {
    const store = { tokens: { ...oldTokens } as OAuthTokens | undefined };
    const provider = createProvider(store);
    const handleToken = vi.fn(invalidGrant);

    await expect(
      auth(provider, { serverUrl, fetchFn: createFetch(handleToken) }),
    ).resolves.toBe('REDIRECT');

    expect(store.tokens).toBeUndefined();
    expect(handleToken).toHaveBeenCalledTimes(1);
    expect(provider.invalidateCredentials).toHaveBeenCalledExactlyOnceWith(
      'tokens',
      { tokens: oldTokens },
    );
    expect(provider.redirectToAuthorization).toHaveBeenCalledOnce();
  });

  it('snapshots the attempted tokens even when the provider mutates its token object', async () => {
    const tokens = { ...oldTokens };
    const store = { tokens: tokens as OAuthTokens | undefined };
    const provider = createProvider(store);
    let attempts = 0;
    const fetchFn = createFetch(() => {
      if (++attempts === 1) {
        Object.assign(tokens, newTokens);
        return invalidGrant();
      }
      return Response.json(newTokens);
    });

    await expect(auth(provider, { serverUrl, fetchFn })).resolves.toBe(
      'AUTHORIZED',
    );
    expect(provider.invalidateCredentials).toHaveBeenCalledExactlyOnceWith(
      'tokens',
      { tokens: oldTokens },
    );
    expect(store.tokens).toMatchObject(newTokens);
  });

  it('supports legacy providers that ignore the invalidation context', async () => {
    const store = { tokens: { ...oldTokens } as OAuthTokens | undefined };
    const provider = createProvider(store);
    provider.invalidateCredentials.mockImplementation(scope => {
      if (scope === 'tokens') store.tokens = undefined;
    });

    await expect(
      auth(provider, { serverUrl, fetchFn: createFetch(invalidGrant) }),
    ).resolves.toBe('REDIRECT');
    expect(store.tokens).toBeUndefined();
  });

  it.each([
    { name: 'existing', tokens: oldTokens },
    { name: 'newer', tokens: newTokens },
    { name: 'absent', tokens: undefined },
  ])(
    'preserves $name credentials when an authorization code is rejected',
    async ({ tokens }) => {
      const store = { tokens };
      // No storedState hook: the rejected code reaches the token endpoint.
      const provider = createProvider(store);
      const handleToken = vi.fn((_params: URLSearchParams) => invalidGrant());

      await expect(
        auth(provider, {
          serverUrl,
          authorizationCode: 'rejected-code',
          fetchFn: createFetch(handleToken),
        }),
      ).rejects.toBeInstanceOf(InvalidGrantError);

      expect(store.tokens).toBe(tokens);
      expect(provider.invalidateCredentials).not.toHaveBeenCalled();
      expect(provider.saveTokens).not.toHaveBeenCalled();
      expect(provider.redirectToAuthorization).not.toHaveBeenCalled();
      expect(handleToken).toHaveBeenCalledExactlyOnceWith(
        expect.any(URLSearchParams),
      );
      expect(handleToken.mock.calls[0][0].get('grant_type')).toBe(
        'authorization_code',
      );
    },
  );

  it('preserves tokens saved while an authorization-code exchange is in flight', async () => {
    const store = { tokens: { ...oldTokens } as OAuthTokens | undefined };
    const provider = createProvider(store);
    const handleToken = vi.fn(() => {
      store.tokens = { ...newTokens };
      return invalidGrant();
    });

    await expect(
      auth(provider, {
        serverUrl,
        authorizationCode: 'rejected-code',
        fetchFn: createFetch(handleToken),
      }),
    ).rejects.toBeInstanceOf(InvalidGrantError);

    expect(store.tokens).toEqual(newTokens);
    expect(provider.invalidateCredentials).not.toHaveBeenCalled();
    expect(handleToken).toHaveBeenCalledOnce();
  });

  it('includes the stored generation when invalidating tokens without an authorization server pin', async () => {
    const store = { tokens: { ...oldTokens } as OAuthTokens | undefined };
    const provider: OAuthClientProvider = {
      ...createProvider(store),
      authorizationServerInformation: undefined,
    };
    const handleToken = vi.fn(() => Response.json(newTokens));

    await expect(
      auth(provider, { serverUrl, fetchFn: createFetch(handleToken) }),
    ).resolves.toBe('REDIRECT');
    expect(provider.invalidateCredentials).toHaveBeenCalledExactlyOnceWith(
      'tokens',
      { tokens: oldTokens },
    );
    expect(handleToken).not.toHaveBeenCalled();
    expect(store.tokens).toBeUndefined();
  });
});

{
  "name": "verify-changesets-action",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --test test.js"
  }
}

import assert from 'node:assert';
import { mock, test } from 'node:test';

import { verifyChangesets } from './index.js';

function mockReadFile(handler) {
  return mock.fn(async (path, encoding) => {
    if (path.endsWith('pre.json')) {
      throw new Error('ENOENT');
    }
    return handler(path, encoding);
  });
}

function mockLstat({ isSymlink = false } = {}) {
  return mock.fn(async () => ({
    isSymbolicLink: () => isSymlink,
  }));
}

test('happy path', async () => {
  const event = {
    pull_request: {
      labels: [],
    },
  };
  const env = {
    CHANGED_FILES: '.changeset/some-happy-path.md',
  };

  const readFile = mockReadFile(
    async () =>
      `---\nai: patch\n@ai-sdk/provider: patch\n---\n## Test changeset`,
  );
  const lstat = mockLstat();

  await verifyChangesets(event, env, readFile, lstat);

  assert.strictEqual(readFile.mock.callCount(), 2);
  assert.deepStrictEqual(readFile.mock.calls[1].arguments, [
    '../../../../.changeset/some-happy-path.md',
    'utf-8',
  ]);
  assert.strictEqual(lstat.mock.callCount(), 1);
});

test('ignores .changeset/README.md', async () => {
  const event = {
    pull_request: {
      labels: [],
    },
  };
  const env = {
    CHANGED_FILES: '.changeset/README.md',
  };

  const readFile = mockReadFile(() => {});
  const lstat = mockLstat();

  await verifyChangesets(event, env, readFile, lstat);

  assert.strictEqual(readFile.mock.callCount(), 1);
  assert.strictEqual(lstat.mock.callCount(), 0);
});

test('invalid file - not a .changeset file', async () => {
  const event = {
    pull_request: {
      labels: [],
    },
  };
  const env = {
    CHANGED_FILES: '.changeset/not-a-changeset-file.txt',
  };

  const readFile = mockReadFile(() => {});
  const lstat = mockLstat();

  await assert.rejects(
    () => verifyChangesets(event, env, readFile, lstat),
    Object.assign(new Error('Invalid file - not a .changeset file'), {
      path: '.changeset/not-a-changeset-file.txt',
    }),
  );

  assert.strictEqual(readFile.mock.callCount(), 1);
});

test('invalid .changeset file - no frontmatter', async () => {
  const event = {
    pull_request: {
      labels: [],
    },
  };
  const env = {
    CHANGED_FILES: '.changeset/invalid-changeset-file.md',
  };

  const readFile = mockReadFile(async () => 'frontmatter missing');
  const lstat = mockLstat();

  await assert.rejects(
    () => verifyChangesets(event, env, readFile, lstat),
    Object.assign(new Error('Invalid .changeset file - no frontmatter found'), {
      path: '.changeset/invalid-changeset-file.md',
    }),
  );
  assert.strictEqual(readFile.mock.callCount(), 2);
  assert.deepStrictEqual(readFile.mock.calls[1].arguments, [
    '../../../../.changeset/invalid-changeset-file.md',
    'utf-8',
  ]);
});

test('minor update', async () => {
  const event = {
    pull_request: {
      labels: [],
    },
  };
  const env = {
    CHANGED_FILES: '.changeset/patch-update.md .changeset/minor-update.md',
  };

  const readFile = mockReadFile(async path => {
    if (path.endsWith('patch-update.md')) {
      return `---\nai: patch\n---\n## Test changeset`;
    }

    return `---\n@ai-sdk/provider: minor\n---\n## Test changeset`;
  });
  const lstat = mockLstat();

  await assert.rejects(
    () => verifyChangesets(event, env, readFile, lstat),
    Object.assign(
      new Error(
        `Invalid .changeset file - invalid version bump (only "patch" is allowed, see https://ai-sdk.dev/docs/migration-guides/versioning). To bypass, add one of the following labels: minor, major`,
      ),
      {
        path: '.changeset/minor-update.md',
        frontmatter: '---\n@ai-sdk/provider: minor\n---',
      },
    ),
  );

  assert.strictEqual(readFile.mock.callCount(), 3);
  assert.deepStrictEqual(readFile.mock.calls[1].arguments, [
    '../../../../.changeset/patch-update.md',
    'utf-8',
  ]);
  assert.deepStrictEqual(readFile.mock.calls[2].arguments, [
    '../../../../.changeset/minor-update.md',
    'utf-8',
  ]);
});

test('minor update - with "minor" label', async () => {
  const event = {
    pull_request: {
      labels: [
        {
          name: 'minor',
        },
      ],
    },
  };
  const env = {
    CHANGED_FILES: '.changeset/patch-update.md .changeset/minor-update.md',
  };

  const readFile = mock.fn(async path => {
    if (path.endsWith('patch-update.md')) {
      return `---\nai: patch\n---\n## Test changeset`;
    }

    return `---\n@ai-sdk/provider: minor\n---\n## Test changeset`;
  });

  const message = await verifyChangesets(event, env, readFile);
  assert.strictEqual(
    message,
    'Skipping changeset verification - "minor" label found',
  );
});

test('major update - with "major" label', async () => {
  const event = {
    pull_request: {
      labels: [
        {
          name: 'major',
        },
      ],
    },
  };
  const env = {
    CHANGED_FILES: '.changeset/patch-update.md .changeset/major-update.md',
  };

  const readFile = mock.fn(async path => {
    if (path.endsWith('patch-update.md')) {
      return `---\nai: patch\n---\n## Test changeset`;
    }

    return `---\n@ai-sdk/provider: major\n---\n## Test changeset`;
  });

  const message = await verifyChangesets(event, env, readFile);
  assert.strictEqual(
    message,
    'Skipping changeset verification - "major" label found',
  );
});

test('major update - allowed when pre-release mode is active', async () => {
  const event = {
    pull_request: {
      labels: [],
    },
  };
  const env = {
    CHANGED_FILES: '.changeset/major-update.md',
  };

  const readFile = mock.fn(async path => {
    if (path.endsWith('pre.json')) {
