import { posix } from 'node:path';
import type { Experimental_SandboxSession as SandboxSession } from '@ai-sdk/provider-utils';
import { harnessStateDirectoryPath, type HarnessV1Bootstrap } from '../../v1';

/**
 * Version of the bootstrap recipe shape itself. Bump to force every existing
 * snapshot/marker to be invalidated regardless of recipe content.
 */
export const BOOTSTRAP_SCHEMA_VERSION = 1;

/**
 * Deterministic 16-char hex identity derived from the recipe's content
 * (harness state directory, harnessId, bootstrapDir, file paths + contents,
 * commands, schema version). The sandbox's concrete HOME is unavailable until
 * creation, so the directory is hashed with a symbolic HOME prefix.
 * Two adapters with equivalent recipes produce the same identity; any
 * content change produces a different identity.
 *
 * Used by sandbox providers as part of the persistent sandbox name so
 * recipe changes automatically invalidate snapshots.
 */
export async function hashHarnessBootstrap(
  recipe: HarnessV1Bootstrap,
): Promise<string> {
  const encoder = new TextEncoder();
  const chunks: Uint8Array[] = [];
  const pushString = (value: string) => {
    chunks.push(encoder.encode(value));
    chunks.push(encoder.encode('\0'));
  };

  pushString(harnessStateDirectoryPath({ sandboxHomeDir: '$HOME' }));
  pushString(recipe.harnessId);
  pushString(recipe.bootstrapDir);

  const sortedFiles = [...recipe.files].sort((a, b) =>
    a.path.localeCompare(b.path),
  );
  for (const file of sortedFiles) {
    pushString(file.path);
    pushString(file.content);
  }

  pushString(JSON.stringify(recipe.commands));
  pushString(String(BOOTSTRAP_SCHEMA_VERSION));

  const totalLength = chunks.reduce((sum, chunk) => sum + chunk.length, 0);
  const buffer = new Uint8Array(totalLength);
  let offset = 0;
  for (const chunk of chunks) {
    buffer.set(chunk, offset);
    offset += chunk.length;
  }

  const digest = await crypto.subtle.digest('SHA-256', buffer);
  const bytes = new Uint8Array(digest);
  let hex = '';
  for (let i = 0; i < 8; i++) {
    hex += bytes[i].toString(16).padStart(2, '0');
  }
  return hex;
}

/**
 * Absolute path of the marker file the framework writes after a recipe runs
 * successfully. Presence of this path inside the sandbox indicates the recipe
 * with the matching `identity` has already been applied.
 */
export function bootstrapMarkerPath({
  recipe,
  identity,
  stateDirectory,
}: {
  recipe: HarnessV1Bootstrap;
  identity: string;
  stateDirectory: string;
}): string {
  return posix.join(
    resolveBootstrapPath({
      path: recipe.bootstrapDir,
      stateDirectory,
    }),
    `.bootstrap-${identity}.ok`,
  );
}

/**
 * Apply a bootstrap recipe to a sandbox session idempotently. Reads the
 * marker file; if it exists, returns immediately. Otherwise creates the
 * bootstrap directory, writes the recipe's files, runs its commands
 * sequentially, and writes the marker on success.
 *
 * Safe to call multiple times. For sandboxes that already contain the
 * recipe (resumed from snapshot, reused across sessions, or applied by
 * an earlier process) this is a single fast read.
 */
export async function applyBootstrapRecipe({
  session,
  recipe,
  identity,
  stateDirectory,
  abortSignal,
}: {
  session: SandboxSession;
  recipe: HarnessV1Bootstrap;
  identity: string;
  stateDirectory: string;
  abortSignal?: AbortSignal;
}): Promise<void> {
  const markerPath = bootstrapMarkerPath({
    recipe,
    identity,
    stateDirectory,
  });

  const existingMarker = await session.readTextFile({
    path: markerPath,
    abortSignal,
  });
  if (existingMarker !== null) {
    return;
  }

  const bootstrapDir = resolveBootstrapPath({
    path: recipe.bootstrapDir,
    stateDirectory,
  });
  const mkdirResult = await session.run({
    command: 'mkdir -p "$BOOTSTRAP_DIR"',
    env: { BOOTSTRAP_DIR: bootstrapDir },
    abortSignal,
  });
  if (mkdirResult.exitCode !== 0) {
    throw new Error(
      `Failed to create bootstrap directory for harness '${recipe.harnessId}' (exit ${mkdirResult.exitCode}): ${bootstrapDir}\n${mkdirResult.stderr || mkdirResult.stdout}`,
    );
  }

  for (const file of recipe.files) {
    await session.writeTextFile({
      path: resolveBootstrapPath({
        path: file.path,
        stateDirectory,
      }),
      content: file.content,
      abortSignal,
    });
  }

  for (const cmd of recipe.commands) {
    const result = await session.run({
      command: cmd.command,
      workingDirectory: bootstrapDir,
      abortSignal,
    });
    if (result.exitCode !== 0) {
      throw new Error(
        `Bootstrap command failed for harness '${recipe.harnessId}' (exit ${result.exitCode}): ${cmd.command}\n${result.stderr || result.stdout}`,
      );
    }
  }

  await session.writeTextFile({
    path: markerPath,
    content: '',
    abortSignal,
  });
}

function resolveBootstrapPath({
  path,
  stateDirectory,
}: {
  path: string;
  stateDirectory: string;
}): string {
  return posix.isAbsolute(path) ? path : posix.resolve(stateDirectory, path);
}

import { describe, expect, it } from 'vitest';
import {
  createDeepAgentsRequestTransformations,
  resolveDeepAgentsAuthenticationMode,
  resolveDeepAgentsEnv,
} from './deepagents-auth';

describe('resolveDeepAgentsEnv', () => {
  it('pins anthropic auth when selected', () => {
    const env = resolveDeepAgentsEnv({
      auth: 'anthropic',
      processEnv: {
        ANTHROPIC_API_KEY: 'sk-ant',
        ANTHROPIC_BASE_URL: 'https://example.test',
        AI_GATEWAY_API_KEY: 'ambient-gw',
      },
    });
    expect(env).toEqual({
      ANTHROPIC_API_KEY: 'sk-ant',
      ANTHROPIC_BASE_URL: 'https://example.test',
    });
  });

  it('passes through an anthropic auth token', () => {
    const env = resolveDeepAgentsEnv({
      auth: 'anthropic',
      processEnv: { ANTHROPIC_AUTH_TOKEN: 'tok' },
    });
    expect(env).toEqual({ ANTHROPIC_AUTH_TOKEN: 'tok' });
  });

  it('routes through the gateway anthropic endpoint (no /v1 suffix)', () => {
    const env = resolveDeepAgentsEnv({
      auth: 'ai-gateway',
      processEnv: { AI_GATEWAY_API_KEY: 'gw-key' },
    });
    expect(env.AI_GATEWAY_API_KEY).toBe('gw-key');
    expect(env.ANTHROPIC_API_KEY).toBe('gw-key');
    expect(env.ANTHROPIC_BASE_URL).toBe('https://ai-gateway.vercel.sh');
  });

  it('trims a trailing slash from a custom gateway base url', () => {
    const env = resolveDeepAgentsEnv({
      auth: 'ai-gateway',
      processEnv: {
        AI_GATEWAY_API_KEY: 'gw-key',
        AI_GATEWAY_BASE_URL: 'https://gw.test/',
      },
    });
    expect(env.ANTHROPIC_BASE_URL).toBe('https://gw.test');
  });

  it('falls back to ambient gateway env before ambient anthropic creds', () => {
    const env = resolveDeepAgentsEnv({
      processEnv: {
        AI_GATEWAY_API_KEY: 'ambient-gw',
        ANTHROPIC_API_KEY: 'ambient-ant',
      },
    });
    expect(env.AI_GATEWAY_API_KEY).toBe('ambient-gw');
    expect(env.ANTHROPIC_API_KEY).toBe('ambient-gw');
    expect(env.ANTHROPIC_BASE_URL).toBe('https://ai-gateway.vercel.sh');
  });

  it('falls back to ambient OIDC token as the gateway key', () => {
    const env = resolveDeepAgentsEnv({
      processEnv: { VERCEL_OIDC_TOKEN: 'oidc-token' },
    });
    expect(env.AI_GATEWAY_API_KEY).toBe('oidc-token');
  });

  it('falls back to ambient anthropic when no gateway creds exist', () => {
    const env = resolveDeepAgentsEnv({
      processEnv: { ANTHROPIC_API_KEY: 'ambient-ant' },
    });
    expect(env).toEqual({ ANTHROPIC_API_KEY: 'ambient-ant' });
  });

  it('does not treat another harness native token as authentication', () => {
    expect(
      resolveDeepAgentsEnv({
        processEnv: { CLAUDE_CODE_OAUTH_TOKEN: 'native-token' },
      }),
    ).toEqual({});
  });

  it('uses a supplied authentication environment instead of ambient credentials', () => {
    const auth = { ANTHROPIC_API_KEY: 'programmatic-anthropic-key' };

    expect(
      resolveDeepAgentsEnv({
        auth,
        processEnv: { AI_GATEWAY_API_KEY: 'ambient-gateway-key' },
      }),
    ).toEqual({ ANTHROPIC_API_KEY: 'programmatic-anthropic-key' });
    expect(
      resolveDeepAgentsAuthenticationMode({
        auth,
        processEnv: { AI_GATEWAY_API_KEY: 'ambient-gateway-key' },
      }),
    ).toBe('anthropic');
  });

  it('rejects nested authentication objects before reading ambient credentials', () => {
    const auth = { anthropic: { apiKey: 'legacy-key' } } as never;

    expect(() =>
      resolveDeepAgentsEnv({
        auth,
        processEnv: { AI_GATEWAY_API_KEY: 'ambient-gateway-key' },
      }),
    ).toThrow(
      'Invalid auth: expected an authentication mode or a flat record with string values.',
    );
    expect(() =>
      resolveDeepAgentsAuthenticationMode({
        auth,
        processEnv: { AI_GATEWAY_API_KEY: 'ambient-gateway-key' },
      }),
    ).toThrow(
      'Invalid auth: expected an authentication mode or a flat record with string values.',
    );
  });

  it('supports string authentication modes', () => {
    expect(
      resolveDeepAgentsEnv({
        auth: 'anthropic',
        processEnv: { ANTHROPIC_API_KEY: 'sk-anthropic' },
      }),
    ).toEqual({ ANTHROPIC_API_KEY: 'sk-anthropic' });

    expect(
      resolveDeepAgentsEnv({
        auth: 'ai-gateway',
        processEnv: { AI_GATEWAY_API_KEY: 'gw-mode' },
      }),
    ).toEqual({
      AI_GATEWAY_API_KEY: 'gw-mode',
      ANTHROPIC_API_KEY: 'gw-mode',
      ANTHROPIC_BASE_URL: 'https://ai-gateway.vercel.sh',
    });
  });
});

