import type { Experimental_DecisionModelV4State as DecisionModelV4State } from '@ai-sdk/provider';
import { describe, it, expect } from 'vitest';
import { createTestServer } from '@ai-sdk/test-server/with-vitest';
import { createGateway } from './gateway-provider';
import { GatewayDecisionModel } from './gateway-decision-model';
import type { GatewayConfig } from './gateway-config';
import {
  GatewayInvalidRequestError,
  GatewayInternalServerError,
} from './errors';

const testState = [
  { type: 'text', text: 'The capital of France is Paris.' },
] as const;

const testQuestions = {
  correct: {
    type: 'boolean' as const,
    instructions: 'Is the statement factually correct?',
  },
  tone: {
    type: 'choice' as const,
    instructions: 'What is the tone?',
    criteria: { neutral: 'Plain and factual.', playful: null },
  },
  quality: {
    type: 'score' as const,
    instructions: 'Rate the quality.',
    criteria: ['Poor.', 'Acceptable.', 'Excellent.'],
  },
};

const dummyAnswers = {
  correct: { type: 'boolean', probability: 0.97 },
  tone: {
    type: 'choice',
    choice: 'neutral',
    probabilities: { neutral: 0.9, playful: 0.1 },
  },
  quality: {
    type: 'score',
    score: 1.8,
    probabilities: { '0': 0.05, '1': 0.1, '2': 0.85 },
  },
};

const server = createTestServer({
  'https://api.test.com/decision-model': {},
});

const createTestModel = (
  config: Partial<
    GatewayConfig & { o11yHeaders?: Record<string, string> }
  > = {},
) =>
  new GatewayDecisionModel('typesafe-ai/jev', {
    provider: 'gateway',
    baseURL: 'https://api.test.com',
    headers: () => ({
      Authorization: 'Bearer test-token',
      'ai-gateway-auth-method': 'api-key',
    }),
    fetch: globalThis.fetch,
    o11yHeaders: config.o11yHeaders || {},
    ...config,
  });

describe('GatewayDecisionModel', () => {
  const statePartsCases: {
    name: string;
    state: DecisionModelV4State;
  }[] = [
    { name: 'a text part', state: [{ type: 'text', text: 'Inspect.' }] },
    {
      name: 'a JSON object part',
      state: [{ type: 'json', value: { product: 'vase', history: ['new'] } }],
    },
    {
      name: 'a JSON array part',
      state: [{ type: 'json', value: ['vase', null] }],
    },
    { name: 'empty parts', state: [] },
    {
      name: 'mixed parts',
      state: [
        { type: 'text', text: 'Inspect.' },
        { type: 'json', value: { product: 'vase' } },
        { type: 'json', value: [1, null] },
      ],
    },
    { name: 'a JSON number', state: [{ type: 'json', value: 1 }] },
    { name: 'JSON null', state: [{ type: 'json', value: null }] },
  ];

  it.each(statePartsCases)(
    'sends $name as ordered state parts',
    async ({ state }) => {
      prepareJsonResponse({});
      await createTestModel().doDecide({ state, questions: testQuestions });
      expect(await server.calls[0].requestBodyJson).toEqual({
        stateParts: state,
        questions: testQuestions,
      });
    },
  );

  it.each([{}, { instructions: undefined }, { instructions: null }])(
    'forwards criteria-only questions with %j',
    async instructionFields => {
      prepareJsonResponse({});
      const questions = {
        correct: {
          type: 'boolean',
          criteria: { true: 'Factually correct' },
          ...instructionFields,
        },
        tone: {
          type: 'choice',
          criteria: testQuestions.tone.criteria,
          ...instructionFields,
        },
        quality: {
          type: 'score',
          criteria: testQuestions.quality.criteria,
          ...instructionFields,
        },
      } as const;
      await createTestModel().doDecide({ state: testState, questions });
      expect((await server.calls[0].requestBodyJson).questions).toStrictEqual(
        JSON.parse(JSON.stringify(questions)),
      );
    },
  );

  it('sends file bytes as base64 in ordered state parts', async () => {
    prepareJsonResponse({});
    await createTestModel().doDecide({
      state: [
        { type: 'text', text: 'Inspect this package.' },
        {
          type: 'file',
          mediaType: 'image/png',
          filename: 'box.png',
          data: { type: 'data', data: new Uint8Array([1, 2, 3]) },
        },
        { type: 'json', value: { product: 'vase' } },
      ],
      questions: testQuestions,
    });

    expect(await server.calls[0].requestBodyJson).toEqual({
      stateParts: [
        { type: 'text', text: 'Inspect this package.' },
        {
          type: 'file',
          mediaType: 'image/png',
          filename: 'box.png',
          data: { type: 'data', data: 'AQID' },
        },
        { type: 'json', value: { product: 'vase' } },
      ],
      questions: testQuestions,
    });
  });

  it('sends base64 file strings unchanged', async () => {
    prepareJsonResponse({});
    const file = {
      type: 'file' as const,
      mediaType: 'image/jpeg',
      data: { type: 'data' as const, data: 'AQID' },
    };
    await createTestModel().doDecide({
      state: [file],
      questions: testQuestions,
    });

    expect(await server.calls[0].requestBodyJson).toEqual({
      stateParts: [file],
      questions: testQuestions,
    });
  });

  it('rejects URL file data before sending a Gateway request', async () => {
    await expect(
      createTestModel().doDecide({
        state: [
          {
            type: 'file',
            mediaType: 'image/png',
            data: { type: 'url', url: new URL('https://example.com/a.png') },
          },
        ],
        questions: testQuestions,
      }),
    ).rejects.toMatchObject({
      name: 'AI_UnsupportedFunctionalityError',
      functionality: 'Gateway decision file input: url data',
    });
    expect(server.calls).toHaveLength(0);
  });

  function prepareJsonResponse({
    answers = dummyAnswers,
    model,
    rounding,
    usage,
    warnings,
    headers,
  }: {
    answers?: Record<string, unknown>;
    model?: string;
    rounding?: { probabilityDecimals?: number; scoreDecimals?: number };
    usage?: { inputTokens?: number; outputTokens?: number };
    warnings?: Array<
      | { type: 'unsupported'; feature: string; details?: string }
      | { type: 'compatibility'; feature: string; details?: string }
      | { type: 'deprecated'; setting: string; message: string }
      | { type: 'other'; message: string }
    >;
    headers?: Record<string, string>;
  } = {}) {
    server.urls['https://api.test.com/decision-model'].response = {
      type: 'json-value',
      headers,
      body: {
        answers,
        ...(model && { model }),
        ...(rounding && { rounding }),
        ...(usage && { usage }),
        ...(warnings && { warnings }),
      },
    };
  }

  it('should report all question types as supported', () => {
    expect(createTestModel().supportedQuestionTypes).toStrictEqual([
      'choice',
      'score',
      'boolean',
    ]);
  });

  it('routes the deprecated factory and model method through the decision protocol', async () => {
    prepareJsonResponse();
    const provider = createGateway({
      baseURL: 'https://api.test.com',
      apiKey: 'test-token',
    });
    expect(provider.evaluationModel).toBe(provider.decisionModel);
    expect(provider.evaluation).toBe(provider.decision);
    await provider
      .evaluationModel('typesafe-ai/jev')
      .doEvaluate({ state: testState, questions: testQuestions });
    expect(server.calls[0].requestUrl).toBe(
      'https://api.test.com/decision-model',
    );
    expect(
      server.calls[0].requestHeaders['ai-decision-model-specification-version'],
    ).toBe('4');
    expect(server.calls[0].requestHeaders).not.toHaveProperty(
      'ai-evaluation-model-specification-version',
    );
  });

  describe('doDecide', () => {
    it('should pass headers correctly', async () => {
      prepareJsonResponse();

      await createTestModel().doDecide({
        state: testState,
        questions: testQuestions,
        headers: { 'Custom-Header': 'test-value' },
      });

      const headers = server.calls[0].requestHeaders;
      expect(headers).toMatchObject({
        authorization: 'Bearer test-token',
        'custom-header': 'test-value',
        'ai-decision-model-specification-version': '4',
        'ai-model-id': 'typesafe-ai/jev',
      });
    });

    it('should include o11y headers', async () => {
      prepareJsonResponse();

      const o11yHeaders = {
        'ai-o11y-deployment-id': 'deployment-1',
        'ai-o11y-environment': 'production',
        'ai-o11y-region': 'iad1',
      } as const;

      await createTestModel({ o11yHeaders }).doDecide({
        state: testState,
        questions: testQuestions,
      });

      const headers = server.calls[0].requestHeaders;
      expect(headers).toMatchObject(o11yHeaders);
    });

    it('should send state and questions in request body', async () => {
      prepareJsonResponse();

      await createTestModel().doDecide({
        state: testState,
        questions: testQuestions,
      });

      expect(await server.calls[0].requestBodyJson).toStrictEqual({
        stateParts: testState,
        questions: testQuestions,
      });
    });

    it('should pass providerOptions into request body', async () => {
      prepareJsonResponse();

      await createTestModel().doDecide({
        state: testState,
        questions: testQuestions,
        providerOptions: { typesafe: { effort: 'high' } },
      });

      const body = await server.calls[0].requestBodyJson;
      expect(body).toMatchObject({
        providerOptions: { typesafe: { effort: 'high' } },
      });
