import {
  APICallError,
  InvalidArgumentError,
  InvalidResponseDataError,
  type Experimental_DecisionModelV4CallOptions as DecisionModelV4CallOptions,
  type LanguageModelV4,
  type LanguageModelV4GenerateResult,
} from '@ai-sdk/provider';
import { WORKFLOW_DESERIALIZE, WORKFLOW_SERIALIZE } from '@workflow/serde';
import { expect, it, vi } from 'vitest';
import { DecisionLanguageModel } from './decision-language-model';

const questions = {
  category: {
    type: 'choice',
    instructions: { task: ['Pick the exact label'] },
    criteria: {
      'Needs Review': { meaning: 'manual' },
      'Needs review': ['automatic'],
      other: null,
    },
  },
  severity: {
    type: 'score',
    instructions: ['Rate the impact'],
    criteria: ['low', { meaning: 'medium' }, null],
  },
} as const;
const options = {
  state: [
    { type: 'json' as const, value: { text: 'test', events: [1, null] } },
  ],
  questions,
};
function setup(overrides: Partial<LanguageModelV4GenerateResult> = {}) {
  const result: LanguageModelV4GenerateResult = {
    content: [{ type: 'text', text: '{"q1":1.25,"q0":"c1"}' }],
    finishReason: { unified: 'stop', raw: 'end' },
    usage: {
      inputTokens: { total: 20, noCache: 15, cacheRead: 5, cacheWrite: 0 },
      outputTokens: { total: 12, text: 8, reasoning: 4 },
    },
    warnings: [{ type: 'other', message: 'test warning' }],
    providerMetadata: { test: { original: true } },
    response: {
      id: 'response',
      modelId: 'resolved',
      timestamp: new Date(0),
      headers: { 'x-request-id': 'id' },
      body: { raw: true },
    },
    ...overrides,
  };
  const doGenerate = vi
    .fn<LanguageModelV4['doGenerate']>()
    .mockResolvedValue(result);
  const languageModel: LanguageModelV4 = {
    specificationVersion: 'v4',
    provider: 'test.language',
    modelId: 'test-model',
    supportedUrls: {},
    doGenerate,
    doStream: vi.fn(),
  };
  return {
    model: new DecisionLanguageModel({
      model: languageModel,
      provider: 'test.decision',
    }),
    doGenerate,
    languageModel,
    result,
  };
}

