import { PassThrough } from 'node:stream';
import { describe, expect, it, vi } from 'vitest';
import { monitorACPAgentStderr } from './agent-stderr-monitor';

describe('monitorACPAgentStderr', () => {
  it('forwards stderr and rejects when the agent cannot deserialize a response stream', async () => {
    const stderr = new PassThrough();
    const onStderrLine = vi.fn();
    const failure = monitorACPAgentStderr({ stderr, onStderrLine });

    stderr.write('ordinary diagnostic\n');
    stderr.write(
      '\u001b[31mERROR\u001b[0m Failed to deserialize ResponseStreamEvent from stream error=invalid response\n',
    );

    await expect(failure).rejects.toThrow(
      'ACP agent failed to deserialize a streamed response.',
    );
    expect(onStderrLine).toHaveBeenNthCalledWith(1, 'ordinary diagnostic');
    expect(onStderrLine).toHaveBeenNthCalledWith(
      2,
      '\u001b[31mERROR\u001b[0m Failed to deserialize ResponseStreamEvent from stream error=invalid response',
    );
  });
});

import { APICallError } from '@ai-sdk/provider';
import {
  WORKFLOW_DESERIALIZE,
  WORKFLOW_SERIALIZE,
} from '@ai-sdk/provider-utils';
import { convertArrayToReadableStream, MockLanguageModelV4 } from 'ai/test';
import { getStepMetadata } from 'workflow';

type MockStreamResult = Awaited<ReturnType<MockLanguageModelV4['doStream']>>;
type MockStreamPart = MockStreamResult extends {
  stream: ReadableStream<infer PART>;
}
  ? PART
  : never;

class SerializableRetryingModel extends MockLanguageModelV4 {
  static [WORKFLOW_SERIALIZE](model: SerializableRetryingModel) {
    return { failuresBeforeSuccess: model.failuresBeforeSuccess };
  }

  static [WORKFLOW_DESERIALIZE](options: { failuresBeforeSuccess: number }) {
    return new SerializableRetryingModel(options.failuresBeforeSuccess);
  }

  constructor(readonly failuresBeforeSuccess: number) {
    let modelAttempts = 0;

    super({
      provider: 'workflow-retry-test',
      modelId: 'workflow-retry-test-model',
      doStream: async () => {
        modelAttempts++;

        if (modelAttempts <= failuresBeforeSuccess) {
          throw new APICallError({
            message: `model call failed on attempt ${modelAttempts}`,
            url: 'https://example.com/model',
            requestBodyValues: {},
            statusCode: 500,
            responseHeaders: { 'retry-after-ms': '0' },
          });
        }

        const text = `model-attempts=${modelAttempts};step-attempt=${getStepMetadata().attempt}`;
        const streamParts: MockStreamPart[] = [
          { type: 'stream-start', warnings: [] },
          { type: 'text-start', id: '1' },
          { type: 'text-delta', id: '1', delta: text },
          { type: 'text-end', id: '1' },
          {
            type: 'finish',
            finishReason: { unified: 'stop', raw: 'stop' },
            usage: {
              inputTokens: {
                total: 1,
                noCache: 1,
                cacheRead: undefined,
                cacheWrite: undefined,
              },
              outputTokens: {
                total: 1,
                text: 1,
                reasoning: undefined,
              },
            },
          },
        ];

        return { stream: convertArrayToReadableStream(streamParts) };
      },
    });
  }
}

// Keep construction outside the workflow module to avoid the SWC closure
// transformation issue tracked in https://github.com/vercel/workflow/issues/1365.
export function retryingModel(): MockLanguageModelV4 {
  return new SerializableRetryingModel(2);
}

import { describe, expect, it } from 'vitest';
import { convertToLanguageModelPrompt } from './convert-to-language-model-prompt';
import { MissingToolResultsError } from '../error/missing-tool-result-error';

describe('tool validation', () => {
  it('should pass validation for provider-executed tools (deferred results)', async () => {
    const result = await convertToLanguageModelPrompt({
      prompt: {
        instructions: undefined,
        messages: [
          {
            role: 'assistant',
            content: [
              {
                type: 'tool-call',
                toolCallId: 'call_1',
                toolName: 'code_interpreter',
                input: { code: 'print("hello")' },
                providerExecuted: true,
              },
            ],
          },
        ],
      },
      supportedUrls: {},
      download: undefined,
    });

    expect(result).toMatchSnapshot();
  });

  it.each([false, true])(
    'should reject an unresolved local approval (follow-up: %s)',
    async followUp => {
      await expect(
        convertToLanguageModelPrompt({
          prompt: {
            instructions: undefined,
            messages: [
              {
                role: 'assistant',
                content: [
                  {
                    type: 'tool-call',
                    toolCallId: 'call_to_approve',
                    toolName: 'dangerous_action',
                    input: { action: 'delete_db' },
                  },
                  {
                    type: 'tool-approval-request',
                    toolCallId: 'call_to_approve',
                    approvalId: 'approval_123',
                  },
                ],
              },
              {
                role: 'tool',
                content: [
                  {
                    type: 'tool-approval-response',
                    approvalId: 'approval_123',
                    approved: true,
                  },
                ],
              },
              ...(followUp
                ? [{ role: 'user' as const, content: 'Continue.' }]
                : []),
            ],
          },
          supportedUrls: {},
          download: undefined,
        }),
      ).rejects.toBeInstanceOf(MissingToolResultsError);
    },
  );

  it('should preserve provider-executed tool-approval-response', async () => {
    const result = await convertToLanguageModelPrompt({
      prompt: {
        instructions: undefined,
        messages: [
          {
            role: 'assistant',
            content: [
              {
                type: 'tool-call',
                toolCallId: 'call_provider_executed',
                toolName: 'mcp_tool',
                input: { action: 'execute' },
                providerExecuted: true,
              },
              {
                type: 'tool-approval-request',
                toolCallId: 'call_provider_executed',
                approvalId: 'approval_provider',
                toolName: 'mcp_tool',
                input: { action: 'execute' },
              } as any,
            ],
          },
          {
            role: 'tool',
            content: [
              {
                type: 'tool-approval-response',
                approvalId: 'approval_provider',
                approved: true,
                providerExecuted: true,
              },
            ],
          },
        ],
      },
      supportedUrls: {},
      download: undefined,
    });

    expect(result).toMatchSnapshot();
  });

  it('should throw error for actual missing results', async () => {
    await expect(async () => {
      await convertToLanguageModelPrompt({
        prompt: {
          instructions: undefined,
          messages: [
            {
              role: 'assistant',
              content: [
                {
                  type: 'tool-call',
                  toolCallId: 'call_missing_result',
                  toolName: 'regular_tool',
                  input: {},
                },
              ],
            },
          ],
        },
        supportedUrls: {},
        download: undefined,
      });
    }).rejects.toThrow(MissingToolResultsError);
  });
});
